typedef struct {
  int cap;
  int **stacks;
  int *sizes;
  int count;
} StackOfPlates;

StackOfPlates *stackOfPlatesCreate(int cap) {
  StackOfPlates *obj = (StackOfPlates *)malloc(sizeof(StackOfPlates));
  obj->cap = cap;
  obj->stacks = (int **)malloc(sizeof(int *) * 2000);
  obj->sizes = (int *)calloc(2000, sizeof(int));
  obj->count = 0;
  return obj;
}

void stackOfPlatesPush(StackOfPlates *obj, int val) {
  if (obj->cap == 0) return;
  if (obj->count == 0 || obj->sizes[obj->count - 1] == obj->cap) {
    obj->stacks[obj->count] = (int *)malloc(sizeof(int) * obj->cap);
    obj->sizes[obj->count] = 0;
    obj->count++;
  }
  obj->stacks[obj->count - 1][obj->sizes[obj->count - 1]++] = val;
}

int stackOfPlatesPop(StackOfPlates *obj) {
  if (obj->count == 0) return -1;
  int v = obj->stacks[obj->count - 1][--obj->sizes[obj->count - 1]];
  if (obj->sizes[obj->count - 1] == 0) {
    free(obj->stacks[obj->count - 1]);
    obj->count--;
  }
  return v;
}

int stackOfPlatesPopAt(StackOfPlates *obj, int index) {
  if (index < 0 || index >= obj->count) return -1;
  int v = obj->stacks[index][--obj->sizes[index]];
  if (obj->sizes[index] == 0) {
    free(obj->stacks[index]);
    for (int i = index; i < obj->count - 1; i++) {
      obj->stacks[i] = obj->stacks[i + 1];
      obj->sizes[i] = obj->sizes[i + 1];
    }
    obj->count--;
  }
  return v;
}

void stackOfPlatesFree(StackOfPlates *obj) {
  for (int i = 0; i < obj->count; i++) free(obj->stacks[i]);
  free(obj->stacks);
  free(obj->sizes);
  free(obj);
}

class StackOfPlates {
  int cap;
  vector<vector<int>> stacks;

public:
  StackOfPlates(int cap) : cap(cap) {}
  void push(int val) {
    if (cap == 0) return;
    if (stacks.empty() || (int)stacks.back().size() == cap) stacks.push_back({});
    stacks.back().push_back(val);
  }
  int pop() {
    if (stacks.empty()) return -1;
    int v = stacks.back().back();
    stacks.back().pop_back();
    if (stacks.back().empty()) stacks.pop_back();
    return v;
  }
  int popAt(int index) {
    if (index < 0 || index >= (int)stacks.size()) return -1;
    int v = stacks[index].back();
    stacks[index].pop_back();
    if (stacks[index].empty()) stacks.erase(stacks.begin() + index);
    return v;
  }
};

type StackOfPlates struct {
	cap    int
	stacks [][]int
}

func Constructor(cap int) StackOfPlates {
	return StackOfPlates{cap: cap}
}

func (s *StackOfPlates) Push(val int) {
	if s.cap == 0 {
		return
	}
	if len(s.stacks) == 0 || len(s.stacks[len(s.stacks)-1]) == s.cap {
		s.stacks = append(s.stacks, []int{})
	}
	last := len(s.stacks) - 1
	s.stacks[last] = append(s.stacks[last], val)
}

func (s *StackOfPlates) Pop() int {
	if len(s.stacks) == 0 {
		return -1
	}
	last := len(s.stacks) - 1
	v := s.stacks[last][len(s.stacks[last])-1]
	s.stacks[last] = s.stacks[last][:len(s.stacks[last])-1]
	if len(s.stacks[last]) == 0 {
		s.stacks = s.stacks[:last]
	}
	return v
}

func (s *StackOfPlates) PopAt(index int) int {
	if index < 0 || index >= len(s.stacks) {
		return -1
	}
	v := s.stacks[index][len(s.stacks[index])-1]
	s.stacks[index] = s.stacks[index][:len(s.stacks[index])-1]
	if len(s.stacks[index]) == 0 {
		s.stacks = append(s.stacks[:index], s.stacks[index+1:]...)
	}
	return v
}

class StackOfPlates {
  private int cap;
  private List<List<Integer>> stacks = new ArrayList<>();

  public StackOfPlates(int cap) {
    this.cap = cap;
  }

  public void push(int val) {
    if (cap == 0) return;
    if (stacks.isEmpty() || stacks.get(stacks.size() - 1).size() == cap) {
      stacks.add(new ArrayList<>());
    }
    stacks.get(stacks.size() - 1).add(val);
  }

  public int pop() {
    if (stacks.isEmpty()) return -1;
    List<Integer> last = stacks.get(stacks.size() - 1);
    int v = last.remove(last.size() - 1);
    if (last.isEmpty()) stacks.remove(stacks.size() - 1);
    return v;
  }

  public int popAt(int index) {
    if (index < 0 || index >= stacks.size()) return -1;
    List<Integer> s = stacks.get(index);
    int v = s.remove(s.size() - 1);
    if (s.isEmpty()) stacks.remove(index);
    return v;
  }
}

class StackOfPlates:
    def __init__(self, cap: int):
        self.cap = cap
        self.stacks = []

    def push(self, val: int) -> None:
        if self.cap == 0:
            return
        if not self.stacks or len(self.stacks[-1]) == self.cap:
            self.stacks.append([])
        self.stacks[-1].append(val)

    def pop(self) -> int:
        if not self.stacks:
            return -1
        v = self.stacks[-1].pop()
        if not self.stacks[-1]:
            self.stacks.pop()
        return v

    def popAt(self, index: int) -> int:
        if index < 0 or index >= len(self.stacks):
            return -1
        v = self.stacks[index].pop()
        if not self.stacks[index]:
            self.stacks.pop(index)
        return v

impl StackOfPlates {
  pub fn new(cap: i32) -> Self {
    StackOfPlates {
      cap: cap as usize,
      stacks: vec![],
    }
  }

  pub fn push(&mut self, val: i32) {
    if self.cap == 0 {
      return;
    }
    if self.stacks.is_empty() || self.stacks.last().unwrap().len() == self.cap {
      self.stacks.push(vec![]);
    }
    self.stacks.last_mut().unwrap().push(val);
  }

  pub fn pop(&mut self) -> i32 {
    if self.stacks.is_empty() {
      return -1;
    }
    let last = self.stacks.last_mut().unwrap();
    let v = last.pop().unwrap();
    if last.is_empty() {
      self.stacks.pop();
    }
    v
  }

  pub fn pop_at(&mut self, index: i32) -> i32 {
    if index < 0 || index as usize >= self.stacks.len() {
      return -1;
    }
    let idx = index as usize;
    let v = self.stacks[idx].pop().unwrap();
    if self.stacks[idx].is_empty() {
      self.stacks.remove(idx);
    }
    v
  }
}

class StackOfPlates {
  private cap: number;
  private stacks: number[][] = [];

  constructor(cap: number) {
    this.cap = cap;
  }

  push(val: number): void {
    if (this.cap === 0) return;
    if (this.stacks.length === 0 || this.stacks[this.stacks.length - 1].length === this.cap) {
      this.stacks.push([]);
    }
    this.stacks[this.stacks.length - 1].push(val);
  }

  pop(): number {
    if (this.stacks.length === 0) return -1;
    const last = this.stacks[this.stacks.length - 1];
    const v = last.pop()!;
    if (last.length === 0) this.stacks.pop();
    return v;
  }

  popAt(index: number): number {
    if (index < 0 || index >= this.stacks.length) return -1;
    const v = this.stacks[index].pop()!;
    if (this.stacks[index].length === 0) this.stacks.splice(index, 1);
    return v;
  }
}
